<?php
$root=realpath($argv[1]??'');if(!$root)throw new RuntimeException('Explicit disposable platform required');$config=require $root.'/_storage/config.php';if($config['database']['host']!=='127.0.0.1'||$config['database']['port']!==3319||empty($config['app']['debug'])||!str_starts_with($config['database']['name'],'bypcms_purchase_'))throw new RuntimeException('Own loopback fixture only');
if(str_contains(file_get_contents($root.'/_core/CommerceOrders.php'),'ModuleReadiness'))throw new RuntimeException('Seed historical records before updating fixture');
define('BYPCMS_ROOT',$root);define('BYPCMS_STORAGE',$root.'/_storage');require $root.'/_core/Database.php';require $root.'/_core/CommerceOrders.php';
$db=new BYPCMS\Core\Database($config);$o=new BYPCMS\Core\CommerceOrders($db,$config,$root);$o->settings->save(['payments_enabled'=>false,'smtp_enabled'=>false],$db);$bank=json_decode(file_get_contents(dirname($root).'/invoice-result.json'),true)['bank_settings'];$o->invoices->bank->save($bank);$owner=(int)$db->one('SELECT u.id FROM byp_users u JOIN byp_roles r ON r.id=u.role_id WHERE r.slug="owner" LIMIT 1')['id'];
$email='legacy-sales-'.bin2hex(random_bytes(5)).'@example.test';$buyer=$db->insert('INSERT INTO byp_customer_accounts(email,name,password_hash,created_at) VALUES(?,?,?,NOW())',[$email,'Historical module purchase QA',password_hash('BYPCMS-QA-Buyer-2026',PASSWORD_DEFAULT)]);$input=['accept_terms'=>true,'accept_privacy'=>true,'legal_version'=>BYPCMS\Core\CommerceLegal::VERSION,'edition'=>'content','term'=>'annual','domain'=>'legacy-sales.example.test','modules'=>['analytics'],'services'=>[]];$ids=[];
foreach(['paid','issued'] as $state){$order=$o->create($buyer,$input+['operation_id'=>bin2hex(random_bytes(16))]);$id=(int)$order['id'];$o->invoices->accept($id,$buyer,$input+['invoice_id'=>$order['invoice']['id']]);if($state==='paid')$o->invoices->confirm($id,$owner,['operation_id'=>bin2hex(random_bytes(16)),'invoice_id'=>$order['invoice']['id'],'amount'=>'13800.00','source'=>'bank','reference'=>'QA-historical-'.bin2hex(random_bytes(6)),'paid_on'=>gmdate('Y-m-d'),'confirmed'=>true]);$ids[$state]=$id;}
$license=$db->one('SELECT l.* FROM byp_license_registry l JOIN byp_license_order_links k ON k.license_id=l.id WHERE k.order_id=?',[$ids['paid']]);unset($license['license_key_hash']);file_put_contents(dirname(__DIR__).'/outputs/module-sales-20261119/legacy-private.json',json_encode(['email'=>$email,'buyer'=>$buyer,'orders'=>$ids,'license'=>$license],JSON_PRETTY_PRINT));echo "Two genuine pre-policy invoice purchases prepared with historical Analytics rights\n";
